def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {
        color: [(r, c) for r in range(h) for c in range(w)
                if grid[r][c] == color]
        for color in (1, 6)
    }

    # Connect same-colored points that are diagonally aligned.
    for color in (1, 6):
        pts = points[color]
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if dr and abs(dr) == abs(dc):
                    sr = 1 if dr > 0 else -1
                    sc = 1 if dc > 0 else -1
                    r, c = r1, c1
                    while True:
                        if out[r][c] == grid[r][c] or out[r][c] == color:
                            out[r][c] = color
                        if (r, c) == (r2, c2):
                            break
                        r += sr
                        c += sc

    # A 6 positioned on a diagonal line defined by two 1s emits a
    # full diagonal line of 6s perpendicular to that line.
    ones, sixes = points[1], points[6]
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if not dr or abs(dr) != abs(dc):
                continue
            for r, c in sixes:
                if (r - r1) * dc == (c - c1) * dr:
                    # Perpendicular direction to the 1-line.
                    sr = 1
                    sc = 1 if dr != dc else -1
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] in (grid[0][0], 6):
                            out[rr][cc] = 6
                        rr -= sr
                        cc -= sc
                    rr, cc = r + sr, c + sc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] in (grid[0][0], 6):
                            out[rr][cc] = 6
                        rr += sr
                        cc += sc
    return out
